def calculate_primary_cluster(features, language):
    """Normalizes features and finds the closest cluster centroid."""
    lang_key = language.lower()
    if lang_key not in LANGUAGE_INFERENCE_BRAINS:
        return "Unknown", 0.0
        
    brain = LANGUAGE_INFERENCE_BRAINS[lang_key]
    medians = np.array(brain['SCALER_MEDIANS'])
    iqrs = np.array(brain['SCALER_IQRS'])
    
    # 1. Robust Scaling (Normalize the features)
    # Avoid division by zero if IQR is 0
    safe_iqrs = np.where(iqrs == 0, 1.0, iqrs)
    scaled_features = (np.array(features) - medians) / safe_iqrs
    
    # Safely find whichever key holds the clusters (e.g., ARCHETYPES_K6, ARCHETYPES_K10)
    arch_key = [k for k in brain.keys() if k.startswith('ARCHETYPES_K')][0]
    
    # 2. Calculate Euclidean distance to every cluster centroid
    min_dist = float('inf')
    best_cluster = "Unknown"
    
    for cluster_name, centroid in brain[arch_key].items():
        centroid_arr = np.array(centroid)
        # Pad or truncate arrays to match lengths just in case of version mismatches
        min_len = min(len(scaled_features), len(centroid_arr))
        
        dist = np.linalg.norm(scaled_features[:min_len] - centroid_arr[:min_len])
        
        if dist < min_dist:
            min_dist = dist
            best_cluster = cluster_name
            
    # Convert distance to a pseudo Z-Score (lower distance = tighter fit)
    return best_cluster, round(min_dist, 3)

def update_database():
    db_path = SCRIPT_DIR / "data" / "gitgalaxy_master.db"
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    
    print("🧠 Booting up Language Inference Brains...")
    
    # Grab all files that have a supported language
    # Add Javascript/Typescript explicitly to handle case sensitivity differences
    supported_langs_list = [lang.capitalize() for lang in LANGUAGE_INFERENCE_BRAINS.keys()] + ['Javascript', 'Typescript']
    supported_langs = tuple(supported_langs_list)
    
    # Use the EXACT 74 features from your schema
    query = f"""
        SELECT 
            id, language, 
            total_loc, coding_loc, comment_loc,
            hit_control_flow_branches, hit_sequential_logic_declarations, hit_function_parameters, 
            hit_function_method_declarations, hit_class_entity_declarations, hit_defensive_programming_constructs, 
            hit_type_safety_bypasses, hit_high_risk_execution_commands, hit_i_o_and_network_boundaries, 
            hit_exposed_api_public_exports, hit_state_mutations_variable_reassignments, hit_commented_out_code_dead_logic, 
            hit_structured_documentation_blocks, hit_unit_test_assertions, hit_asynchronous_concurrent_execution, 
            hit_ui_view_layer_components, hit_closures_and_anonymous_functions, hit_global_state_dependencies, 
            hit_decorators_and_annotations, hit_generic_type_abstractions, hit_collection_iterators_comprehensions, 
            hit_scientific_and_mathematical_operations, hit_metaprogramming_and_reflection, hit_module_dependencies_imports, 
            hit_authorship_metadata, hit_planned_work_todos, hit_acknowledged_tech_debt_fixmes, 
            hit_specification_traceability_tags, hit_indentation_faction, hit_server_side_rendering_contexts, 
            hit_event_publishers_emitters, hit_dependency_injection_constructs, hit_preprocessor_macros, 
            hit_pointer_arithmetic_and_addressing, hit_manual_memory_allocation, hit_inline_assembly_blocks, 
            hit_structured_telemetry_and_logging, hit_ad_hoc_print_debug_statements, hit_explicit_type_casts, 
            hit_fatal_aborts_and_exceptions, hit_thread_sleeps_and_blocking_waits, hit_bitwise_operations, 
            hit_thread_synchronization_locks, hit_immutable_data_declarations, hit_resource_deallocation_and_cleanup, 
            hit_private_encapsulated_scopes, hit_event_listeners_and_subscribers, hit_bypassed_skipped_tests, 
            hit_structural_tab_indentations, hit_structural_space_indentations, hit_hardware_bridge, 
            hit_cryptography, hit_auth_middleware, hit_ipc_rpc_bridges, hit_feature_flags, 
            hit_serialization_parsing, hit_regex_execution, hit_time_date_logic, hit_high_entropy_obfuscated_logic, 
            hit_safety_and_constraint_bypasses, hit_external_network_and_i_o_hooks, hit_dynamic_code_execution_eval_exec, 
            hit_global_environment_mutation, hit_commented_out_executable_logic, hit_low_level_bitwise_cryptographic_math, 
            hit_non_standard_steganographic_imports, hit_non_standard_unicode_homoglyphs, hit_embedded_credentials_and_keys, 
            hit_sec_extension_mismatch, hit_sec_entropy, hit_sec_tainted_injection
        FROM galactic_census 
        WHERE language IN {supported_langs}
    """
    
    cursor.execute(query)
    rows = cursor.fetchall()
    print(f"📊 Analyzing {len(rows)} compatible files...")
    
    updates = []
    
    for row in rows:
        file_id = row[0]
        language = row[1]
        
        # Extract the exact 74 numeric features used for scaling
        features = list(row[2:]) 
        
        # Fill any None values with 0.0 before doing math
        features = [0.0 if x is None else float(x) for x in features]
        
        primary_match, z_score = calculate_primary_cluster(features, language)
        
        updates.append((primary_match, z_score, file_id))
        
    print("💾 Committing new cluster fingerprints to database...")
    cursor.executemany("UPDATE galactic_census SET archetype = ?, repo_z_score = ? WHERE id = ?", updates)
    conn.commit()
    conn.close()
    
    print("✅ Inference complete. Database ready for multi-class XGBoost.")

if __name__ == "__main__":
    update_database()